8125	    private void emitFnApp(_RewriteFnApp x) {
8126	        // This is a little weird.  If a function takes no arguments the parser gives me a void literal expr
8127	        // however I don't want to be putting a void literal on the stack because it gets in the way.
8128	        int savedParamCount = paramCount;
8129	        boolean savedFnRefIsApply = fnRefIsApply;
8130	        try {
8131	            Expr arg = x.getArgument();
8132	            Expr fn = x.getFunction();
8133	            
8134	            // need to use closure if fn is generic and instantiating with a
8135	            // tuple type for the entire parameter list.
8136	            boolean useClosure =
8137	                !(fn instanceof FunctionalRef) 
8138	                || ((FunctionalRef) fn).getStaticArgs().size() > 0
8139	                || (fn instanceof FnRef && localFunctionOrNull((FnRef) fn) != null)
8140	                ;
8141	                
8142	            if (useClosure) {
8143	                if (fn instanceof FunctionalRef && ((FunctionalRef) fn).getStaticArgs().size() > 0 &&
8144	                    assumptionCount(callArgList(arg)) > 0)
8145	                    refuseGenericAssumption((FunctionalRef) fn);
8146	                // Higher-order call.
8147	                fn.accept(this); // Puts the VarRef function on the stack.
8148	            }
8149	            fnRefIsApply = false;
8150	            Type domain_type = ((ArrowType)(x.getFunction().getInfo().getExprType().unwrap())).getDomain();
8151	            evalArg(x, domain_type, arg);
8152	            fnRefIsApply = true;
8153	            if (useClosure) {
8154	                generateHigherOrderCall(exprType(fn));
8155	            } else {
8156	                callArgsForAssumption = callArgList(arg);
8157	                try {
8158	                    x.getFunction().accept(this);
8159	                } finally {
8160	                    callArgsForAssumption = null;
8161	                }
8162	            }
8163	        } finally {
8164	            paramCount = savedParamCount;
8165	            fnRefIsApply = savedFnRefIsApply;
8166	        }
8167	    }
