3285	    private List<VarCodeGen> addParams(List<Param> params, int selfIndex) {
3286	        
3287	        /* Special case 
3288	         * If there is just one parameter, and it is a tuple, then we need to
3289	         * monkey with the params a wee bit.
3290	         */
3291	        
3292	        List<VarCodeGen> paramsGen = new ArrayList<VarCodeGen>(params.size());
3293	        int index = 0;
3294	        
3295	        if (params.size() == 1 && selfIndex == Naming.NO_SELF && 
3296	                (params.get(0).getIdType().unwrap() instanceof TupleType) ) {
3297	            Param p0 = params.get(0);
3298	            TupleType tuple_type = ((TupleType) p0.getIdType().unwrap());
3299	            List<Type> tuple_types = tuple_type.getElements();
3300	            if (tuple_types.size() == 0) return new ArrayList<VarCodeGen>(); //actually a single void parameter - don't pass it
3301	            Id tuple_name = p0.getName();
3302	            String tuple_name_string = tuple_name.getText();
3303	                        
3304	            index = Naming.TUPLE_ORIGIN;
3305	            for (Type t : tuple_types) {
3306	                Id id = NodeFactory.makeId(tuple_name, tuple_name_string + index);
3307	                Param p = NodeFactory.makeParam(id, t);
3308	                VarCodeGen v = addParam(p);
3309	                paramsGen.add(v);
3310	                index++;
3311	            }
3312	            
3313	            /* 
3314	             * Next construct a local var, a tuple, from the parameters.
3315	             * Perhaps it will go unused, in which case dead code elimination
3316	             * in the JIT will clean it out for us.
3317	             * 
3318	             * First push everything, then invoke the appropriate static make
3319	             * method from the tuple type, then add the result as a local var.
3320	             */
3321	            
3322	            VarCodeGen vcg = new VarCodeGen.LocalVar(tuple_name, tuple_type, this);
3323	            
3324	            addLocalVar(vcg);
3325	            paramsGen.add(vcg);
3326	            
3327	            index = Naming.TUPLE_ORIGIN;
3328	            for (Type t : tuple_types) {
3329	                Id id = NodeFactory.makeId(tuple_name, tuple_name_string + index);
3330	                VarCodeGen vcge = getLocalVarOrNull(id);
3331	                vcge.pushValue(mv);
3332	                index++;
3333	            }
3334	            
3335	            makeTupleOfSpecifiedType(tuple_type);
3336	            
3337	            vcg.assignValue(mv);
3338	            
3339	        } else {
3340	            for (Param p : params) {
3341	                if (index != selfIndex) {
3342	                    VarCodeGen v = addParam(p);
3343	                    paramsGen.add(v);
3344	                }
3345	                index++;
3346	            }
3347	        }
