7412	    /*
7413	     * Whether the generic method that a dotted call names, with nsargs static arguments, at the
7414	     * tuple domain_type, declares one parameter: a generic declaration of the name that the
7415	     * receiver's type holds with nsargs static parameters declares one, and none declares a
7416	     * parameter for each of the tuple's elements.  A declaration of another number of
7417	     * parameters cannot take the call.
7418	     */
7419	    private boolean genericMethodTakesOneParameter(Type receiverType, IdOrOp method, int nsargs,
7420	                                                   Type domain_type) {
7421	        if (!(domain_type instanceof TupleType) || NodeUtil.isVoidType(domain_type)) return false;
7422	        if (!(receiverType instanceof TraitType)) return false;
7423	        int n = ((TupleType) domain_type).getElements().size();
7424	        boolean one = false;
7425	        for (scala.Tuple3<Functional, StaticTypeReplacer, TraitType> m :
7426	                 methodsNamed((TraitType) receiverType, method, Naming.NO_SELF)) {
7427	            Functional fnl = m._1();
7428	            if (fnl.staticParameters().size() != nsargs) continue;
7429	            int k = fnl.parameters().size();
7430	            if (k == 1) one = true;
7431	            else if (k == n) return false;
7432	        }
7433	        return one;
7434	    }

