763	     */
764	    public static Type getParamType(Type type, int i, int paramCount,
765	                                    TypeAnalyzer ta) {
766	        Type r0;
767	        if (type instanceof ArrowType) {
768	            ArrowType at = (ArrowType) type;
769	            r0 = at.getDomain();
770	
771	            // Ensure that the domain count matches the paramCount
772	            if (r0 instanceof TupleType) {
773	                TupleType tt = (TupleType) r0;
774	                if (paramCount != tt.getElements().size())
775	                    r0 = null;
776	                else
777	                    r0 = tt.getElements().get(i);
778	            } else if (paramCount != 1) {
779	                r0 = null;
780	            }
781	        } else if (type instanceof IntersectionType) {
782	            r0 = getParamType((IntersectionType) type, i, paramCount, ta);
783	        } else {
784	            throw new CompilerError("Non arrowtype " + type + " in (function) intersection type");
785	        }
786	        return r0;
787	    }
