320	    public void split(boolean computeSubsets) {
321	        /* First determine if there are any overload subsets.
322	           This matters because it may affect naming
323	           of the leaf (single) functions.
324	         */
325	        if (CodeGenerationPhase.debugOverloading >= 1)
326	            System.err.println(
327	                    Useful.listInDelimiters("Split [" , lessSpecificThanSoFar, "]", "\n      "));
328	
329	
330	        TopSortItemImpl<TaggedFunctionName>[] pofuns =
331	            new OverloadSet.POTFN[lessSpecificThanSoFar.size()];
332	        /* Convert set of dispatch types into something that can be
333	         * (topologically) sorted. */
334	        {
335	            int i = 0;   
336	
337	            for (TaggedFunctionName f : lessSpecificThanSoFar ) {
338	                pofuns[i] = new POTFN(f);
339	                i++;
340	            }
341	        }
342	
343	        for (int fi = 0; fi < pofuns.length; fi++) {
344	            TaggedFunctionName f = pofuns[fi].x;
345	            int i = 1; // for self
346	            /* Count the number of functions in LSTSF that are more
347	             * specific than or equal to f.
348	             * Also record any more-specific-than relationship encountered.
349	             */
350	            for (int gi = 0; gi < pofuns.length; gi++) {
351	                TaggedFunctionName g = pofuns[gi].x;
352	                if (!(f == g)) {
353	                    if (fLessSpecThanG(f, g)) {
354	                        if (CodeGenerationPhase.debugOverloading >= 3)
355	                            System.err.println(g.toString() + " is <= " + f.toString());
356	                        i++;
357	                        pofuns[gi].edgeTo(pofuns[fi]);
358	                    }
359	                }
360	            }
361	            if (computeSubsets) {
362	
363	                if (i > 1) {
364	                    /* There's at least one function more specific than f. */
365	                    if (i == lessSpecificThanSoFar.size()) {
366	                        /*
367	                         * If f is more specific than or equal to every member
368	                         * of LSTSF, then it is the principal member.
369	                         */
370	                        principalMember = f;
371	                    } else {
372	                        /* 
373	                         * There are SOME members of the subset that are more
374	                         * specific than f; identify those, and create that
375	                         * subset.  f will be the principal member of the
376	                         * overloaded function that results.  External (through
377	                         * API) references to f, must invoke the overloaded
378	                         * function.
379	                         */
380	                        HashSet<TaggedFunctionName> subLSTSF =
381	                            new HashSet<TaggedFunctionName>();
382	                        subLSTSF.add(f);
383	                        for (TaggedFunctionName g : lessSpecificThanSoFar) {
384	                            if (!(f == g)) {
385	                                if (fLessSpecThanG(f, g)) {
386	                                    subLSTSF.add(g);
387	                                }
388	                            }
389	                        }
390	                        OverloadSet subset = makeSubset(subLSTSF, f, this);
391	                        subset.overloadSubsets = overloadSubsets;
392	                        String overload_name = subset.compute_overload_name(f);
393	                            // I don't think this key is right for generics.
394	                        overloadSubsets.put(overload_name , subset);
395	                        subset.addExtraKeys(f, otherOverloadKeys);
396	                    }
397	                }
398	            }
399	        }
400	
401	        TaggedFunctionName nameTemp = pofuns[0].x;
402	        List<TopSortItemImpl<TaggedFunctionName>> specificFirst;
403	        try {
404	            specificFirst = TopSort.depthFirstArray(pofuns);
405	        } catch (CycleInRelation ex) {
406	
407		    for (int fi = 0; fi < pofuns.length; fi++) {
408			System.out.println("# " + pofuns[fi].x);
409		    }
410	            throw new CompilerBug(
411	"Likely bug in static analysis, apparently malformed overload set not rejected for\n" +
412	nameTemp + "\n" +
413	"Probable cause is a functional method and top level function with same signature.", ex);
414	        }
415	        
416	        if (computeSubsets) {
417	            /*
418	             * After identifying all the subsets (which have principal
419	             * members), generate their structure.
420	             */
421	            for (OverloadSet subset : overloadSubsets.values()) {
422	                subset.splitInternal(specificFirst);
423	            }
424	        }
425	
426	        // I don't think this key is right for generics.
427	        if (principalMember != null) {
428	            String overload_name = compute_overload_name(principalMember);
429	            overloadSubsets.put(overload_name, this);
430	            addExtraKeys(principalMember, otherOverloadKeys);
431	        }
432	
433	        /* Split set into dispatch tree. */
434	        splitInternal(specificFirst);
435	
436	    }
