488	    private void splitInternal(List<TopSortItemImpl<TaggedFunctionName>> funsInSpecificOrder) {
489	        if (splitDone)
490	            return;
491	
492	        int l = lessSpecificThanSoFar.size();
493	        
494	        specificDispatchOrder = new TaggedFunctionName[l];
495	        {
496	            int i = 0;
497	
498	            for (TopSortItemImpl<TaggedFunctionName> tsii_f : funsInSpecificOrder) {
499	                TaggedFunctionName f = tsii_f.x;
500	                if (lessSpecificThanSoFar.contains(f))
501	                    specificDispatchOrder[i++] = f;
502	            }
503	        }
504	        
505	        if (l == 1) {
506	            splitDone = true;
507	            return;
508	            // If there are no other alternatives, then we are done.
509	        }
510	        
511	        splitDone = true;
512	    }
